package mz.bam.seeky.android;
public class CloudProtocolTest {
 static int n;static void ok(boolean b,String m){if(!b)throw new AssertionError(m);n++;System.out.println("PASS "+m);}static void bad(Runnable r,String m){try{r.run();throw new AssertionError(m);}catch(IllegalArgumentException|IllegalStateException e){ok(true,m);}}
 public static void main(String[] args){String verifier="dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";ok(CloudProtocol.challenge(verifier).equals("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"),"PKCE SHA256 matches RFC7636 vector");String random=CloudProtocol.random();ok(random.length()==43&&random.matches("[A-Za-z0-9_-]+"),"PKCE verifier has cryptographic length and URL-safe alphabet");ok(CloudProtocol.base("https://abc.supabase.co/").equals("https://abc.supabase.co"),"cloud endpoint canonicalizes HTTPS project host");bad(()->CloudProtocol.base("http://abc.supabase.co"),"cleartext cloud endpoint rejected");bad(()->CloudProtocol.base("https://abc.supabase.co.evil.test"),"lookalike cloud host rejected");bad(()->CloudProtocol.base("https://user@abc.supabase.co"),"embedded endpoint credentials rejected");bad(()->CloudProtocol.base("https://abc.supabase.co/path"),"unexpected endpoint path rejected");String url=CloudProtocol.authorize("https://abc.supabase.co","sb_publishable_publickey","google",verifier,"state_1");ok(url.contains("code_challenge_method=s256")&&!url.contains(verifier),"OAuth URL sends challenge and never sends verifier");ok(CloudProtocol.callback("seekyestudos://auth/callback?state=state_1&code=abc","state_1",100,200).equals("abc"),"valid OAuth callback returns one authorization code");bad(()->CloudProtocol.callback("seekyestudos://auth/callback?state=wrong&code=abc","state_1",100,200),"login state mismatch rejected");bad(()->CloudProtocol.callback("seekyestudos://auth/callback?state=state_1&code=abc&code=def","state_1",100,200),"duplicate callback parameters rejected");bad(()->CloudProtocol.callback("https://auth/callback?state=state_1&code=abc","state_1",100,200),"unregistered callback scheme rejected");bad(()->CloudProtocol.callback("seekyestudos://other/callback?state=state_1&code=abc","state_1",100,200),"unregistered callback host rejected");bad(()->CloudProtocol.callback("seekyestudos://auth/callback?state=state_1&code=abc#token=bad","state_1",100,200),"implicit fragment credentials rejected");bad(()->CloudProtocol.callback("seekyestudos://auth/callback?state=state_1&code=abc","state_1",100,900000),"expired login initiation rejected");bad(()->CloudProtocol.callback("seekyestudos://auth/callback?state=state_1&error=access_denied","state_1",100,200),"provider refusal does not create a session");ok(!CloudProtocol.canPublish("ownerA","ownerB",4,4),"different account cannot publish another local workspace");ok(!CloudProtocol.canPublish("ownerA","ownerA",4,5),"stale phone cannot overwrite newer remote revision");ok(CloudProtocol.canPublish("ownerA","ownerA",5,5),"current same-account workspace may publish");ok(CloudProtocol.object("11111111-1111-4111-8111-111111111111","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",2).endsWith("/00002.bin"),"chunk path is deterministic and namespaced");bad(()->CloudProtocol.object("../escape","id",0),"cloud object traversal rejected");bad(()->CloudProtocol.object("11111111-1111-4111-8111-111111111111","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",64),"chunk count cannot exceed snapshot bound");System.out.println(n+" cloud protocol checks");}
}
